/* Motor original do Fluxo V2: fonte React/bundle preservada, dados virtualizados vindos de documento.json local. */
try{window.localStorage.getItem('__aj_probe__')}catch(e){try{Object.defineProperty(window,'localStorage',{configurable:true,value:(()=>{const x={};return{getItem:k=>Object.prototype.hasOwnProperty.call(x,k)?x[k]:null,setItem:(k,v)=>{x[k]=String(v)},removeItem:k=>delete x[k],clear:()=>{for(const k in x)delete x[k]},key:i=>Object.keys(x)[i]||null,get length(){return Object.keys(x).length}}})()})}catch(_){}}
window.__FLOW_EXTERNAL_CONFIG__={dataBaseUrl:'https://standalone.local/data/',uiLibraryContentBaseUrl:'https://standalone.local/library/',flowFile:'flow_master.json'};
const DOCUMENTO_FLUXO_VISUAL=await fetch(new URL('./documento.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('documento.json indisponível');return r.json()});
window.__STANDALONE_VFS__={...DOCUMENTO_FLUXO_VISUAL.recursosLocais,
 'https://standalone.local/data/flow_master.json':{body:JSON.stringify(DOCUMENTO_FLUXO_VISUAL.fluxo),mime:'application/json;charset=utf-8'}
};
const nativeFetch=window.fetch.bind(window);
window.fetch=async function(input,init){
 const url=typeof input==='string'?input:(input&&input.url)||String(input);
 const hit=window.__STANDALONE_VFS__[url.split('#')[0]];
 if(hit!==undefined)return new Response(hit.body,{status:200,headers:{'Content-Type':hit.mime||'text/plain;charset=utf-8','Cache-Control':'no-store'}});
 return nativeFetch(input,init);
};
const queryPreview=new URLSearchParams(location.search).get('preview');
if(queryPreview)window.__FLOW_PREVIEW_SCREEN__=queryPreview;
window.__FLOW_OPEN_PREVIEW_URL__=(screenKey)=>new URL('./index.html?preview='+encodeURIComponent(screenKey),location.href).href;

const decode=(s)=>new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0)));
const repoCode=decode('');
const repoUrl=URL.createObjectURL(new Blob([repoCode],{type:'text/javascript'}));
const patch=(code)=>code.replaceAll('./flow-master-repository--fNWQSur.js',repoUrl);
const isPreview=new URLSearchParams(location.search).get('__preview')==='1'||Boolean(window.__FLOW_PREVIEW_SCREEN__);
if(isPreview){
  document.getElementById('root').style.display='none';
  const pr=document.getElementById('flow-preview-root'); pr.style.display='block';
  const code=patch(decode(''));
  const u=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));
  import(u);
} else {
  document.getElementById('flow-preview-root').style.display='none';
  const code=patch(decode(''));
  const u=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));
  import(u);
}
